package mihon.core.migration

import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Deferred
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.runBlocking

object Migrator {

    private var result: Deferred<Boolean>? = null
    val scope = CoroutineScope(Dispatchers.IO + Job())

    fun initialize(
        old: Int,
        new: Int,
        migrations: List<Migration>,
        dryrun: Boolean = false,
        onMigrationComplete: () -> Unit,
    ) {
        val migrationContext = MigrationContext(dryrun, old)
        val migrationJobFactory = MigrationJobFactory(migrationContext, scope)
        val migrationStrategyFactory = MigrationStrategyFactory(migrationJobFactory, onMigrationComplete)
        val strategy = migrationStrategyFactory.create(old, new)
        result = strategy(migrations)
    }

    suspend fun await(): Boolean {
        val result = result ?: CompletableDeferred(false)
        return result.await()
    }

    fun release() {
        result = null
    }

    fun awaitAndRelease(): Boolean = runBlocking {
        await().also { release() }
    }
}

package tachiyomi.core.common.preference

import android.content.Context
import android.content.SharedPreferences
import androidx.preference.PreferenceManager
import kotlinx.coroutines.channels.awaitClose
import kotlinx.coroutines.flow.callbackFlow
import tachiyomi.core.common.preference.AndroidPreference.BooleanPrimitive
import tachiyomi.core.common.preference.AndroidPreference.FloatPrimitive
import tachiyomi.core.common.preference.AndroidPreference.IntPrimitive
import tachiyomi.core.common.preference.AndroidPreference.LongPrimitive
import tachiyomi.core.common.preference.AndroidPreference.ObjectAsInt
import tachiyomi.core.common.preference.AndroidPreference.ObjectAsString
import tachiyomi.core.common.preference.AndroidPreference.ObjectSetAsStringSet
import tachiyomi.core.common.preference.AndroidPreference.StringPrimitive
import tachiyomi.core.common.preference.AndroidPreference.StringSetPrimitive

class AndroidPreferenceStore(
    context: Context,
    private val sharedPreferences: SharedPreferences = PreferenceManager.getDefaultSharedPreferences(context),
) : PreferenceStore {

    private val keyFlow = sharedPreferences.keyFlow

    override fun getString(key: String, defaultValue: String): Preference<String> {
        return StringPrimitive(sharedPreferences, keyFlow, key, defaultValue)
    }

    override fun getLong(key: String, defaultValue: Long): Preference<Long> {
        return LongPrimitive(sharedPreferences, keyFlow, key, defaultValue)
    }

    override fun getInt(key: String, defaultValue: Int): Preference<Int> {
        return IntPrimitive(sharedPreferences, keyFlow, key, defaultValue)
    }

    override fun getFloat(key: String, defaultValue: Float): Preference<Float> {
        return FloatPrimitive(sharedPreferences, keyFlow, key, defaultValue)
    }

    override fun getBoolean(key: String, defaultValue: Boolean): Preference<Boolean> {
        return BooleanPrimitive(sharedPreferences, keyFlow, key, defaultValue)
    }

    override fun getStringSet(key: String, defaultValue: Set<String>): Preference<Set<String>> {
        return StringSetPrimitive(sharedPreferences, keyFlow, key, defaultValue)
    }

    override fun <T> getObjectFromString(
        key: String,
        defaultValue: T,
        serializer: (T) -> String,
        deserializer: (String) -> T,
    ): Preference<T> {
        return ObjectAsString(
            preferences = sharedPreferences,
            keyFlow = keyFlow,
            key = key,
            defaultValue = defaultValue,
            serializer = serializer,
            deserializer = deserializer,
        )
    }

    override fun <T> getObjectFromInt(
        key: String,
        defaultValue: T,
        serializer: (T) -> Int,
        deserializer: (Int) -> T,
    ): Preference<T> {
        return ObjectAsInt(
            preferences = sharedPreferences,
            keyFlow = keyFlow,
            key = key,
            defaultValue = defaultValue,
            serializer = serializer,
            deserializer = deserializer,
        )
    }

    override fun <T> getObjectSetFromStringSet(
        key: String,
        defaultValue: Set<T>,
        serializer: (T) -> String,
        deserializer: (String) -> T?,
    ): Preference<Set<T>> {
        return ObjectSetAsStringSet(
            preferences = sharedPreferences,
            keyFlow = keyFlow,
            key = key,
            defaultValue = defaultValue,
            serializer = serializer,
            deserializer = deserializer,
        )
    }

    override fun getAll(): Map<String, *> {
        return sharedPreferences.all ?: emptyMap<String, Any>()
    }
}

private val SharedPreferences.keyFlow
    get() = callbackFlow {
        val listener = SharedPreferences.OnSharedPreferenceChangeListener { _, key: String? ->
            trySend(
                key,
            )
        }
        registerOnSharedPreferenceChangeListener(listener)
        awaitClose {
            unregisterOnSharedPreferenceChangeListener(listener)
        }
    }

package mihon.data.ocr

import java.io.File
import java.util.concurrent.locks.ReentrantReadWriteLock
import kotlin.concurrent.read
import kotlin.concurrent.write

/**
 * Пользовательский словарь OCR.
 *
 * Слова, добавленные на карточке результата («＋ Словарь»), вручную в
 * настройках или накопленные при считывании глав. Используется вторым
 * источником слов (после встроенного [RuWordList]):
 *  * [OcrTextCleaner.splitGluedRun] разбивает слипшиеся прогоны капса и по
 *    словам пользователя — без этого «имя персонажа» не делилось на слова;
 *  * [CyrillicOcrEngine.candidateQuality] даёт бонус кандидату v3/v5, слова
 *    которого реально есть в словаре, — выбор «читаемого» результата.
 *
 * Это не словарная коррекция: словарь только разбивает/подсвечивает уже
 * распознанное, ничего не подменяя.
 *
 * Хранилище — текстовый файл (UTF-8, одно слово на строку, регистр не
 * важен). Путь задаётся [configure] на старте приложения; без файла словарь
 * живёт в памяти (режим тестов).
 */
object OcrVocabulary {

    private val lock = ReentrantReadWriteLock()

    @Volatile
    private var file: File? = null

    private val lower = HashSet<String>()
    private val upper = HashSet<String>()

    /** Максимальная длина слова — дольше не бывает осмысленного токена. */
    private const val MAX_WORD_LEN = 48

    /**
     * Привязывает словарь к файлу и загружает его. null/пустая строка =
     * только оперативная память (тесты). Замена файла очищает словарь.
     */
    fun configure(path: String?) {
        lock.write {
            file = path?.takeIf { it.isNotBlank() }?.let { File(it) }
            lower.clear()
            upper.clear()
            val active = file
            if (active != null && active.exists()) {
                runCatching {
                    active.useLines { lines ->
                        for (line in lines) {
                            val word = line.trim()
                            if (word.isNotEmpty() && word.length <= MAX_WORD_LEN) {
                                lower.add(word.lowercase())
                                upper.add(word.uppercase())
                            }
                        }
                    }
                }
            }
        }
    }

    /** Добавляет все буквенно-цифровые токены текста. Возвращает число новых слов. */
    fun addFromText(text: String): Int {
        if (text.isBlank()) return 0
        var added = 0
        lock.write {
            text.split(Regex("[^\\p{L}\\p{N}-]+"))
                .map(String::trim)
                .filter { it.length in 2..MAX_WORD_LEN }
                .forEach { raw ->
                    // Разрешаем и кириллицу, и латынь, и смешанные токены
                    // («Wi-Fi»), чтобы пользователь мог учить двигатель своим
                    // словам. Пунктуация уже отрезана разбиением.
                    if (upper.add(raw.uppercase())) {
                        lower.add(raw.lowercase())
                        added++
                    }
                }
            if (added > 0) persistLocked()
        }
        return added
    }

    /** Добавляет одно слово. Возвращает true, если слово реально добавлено. */
    fun addWord(word: String): Boolean {
        val clean = word.trim()
        if (clean.isEmpty() || clean.length > MAX_WORD_LEN) return false
        lock.write {
            if (upper.add(clean.uppercase())) {
                lower.add(clean.lowercase())
                persistLocked()
                return true
            }
        }
        return false
    }

    /** Удаляет слово. Возвращает true, если слово было в словаре. */
    fun removeWord(word: String): Boolean {
        val clean = word.trim()
        if (clean.isEmpty()) return false
        lock.write {
            if (upper.remove(clean.uppercase())) {
                lower.remove(clean.lowercase())
                persistLocked()
                return true
            }
        }
        return false
    }

    fun clear() {
        lock.write {
            lower.clear()
            upper.clear()
            persistLocked()
        }
    }

    fun size(): Int = lock.read { upper.size }

    fun words(): List<String> = lock.read { lower.toList().sorted() }

    /** Правда, если слово есть в пользовательском словаре (без учёта регистра). */
    fun isUserWord(word: String): Boolean {
        if (word.isEmpty()) return false
        return lock.read { upper.contains(word.uppercase()) }
    }

    /** Правда, если слово есть в пользовательском словаре ИЛИ в [RuWordList]. */
    fun isKnownWord(word: String): Boolean {
        if (word.isEmpty()) return false
        val up = word.uppercase()
        if (up in RuWordList.upper) return true
        return lock.read { upper.contains(up) }
    }

    private fun persistLocked() {
        val active = file ?: return
        runCatching {
            val parent = active.parentFile
            if (parent != null && !parent.exists()) parent.mkdirs()
            // Атомарная замена: пишем во временный файл, затем переименовываем.
            // Это защищает от «оборванной» записи при случайном падении процесса.
            val tmp = File(active.parentFile, active.name + ".tmp")
            tmp.writeText(lower.joinToString("\n", postfix = "\n"))
            val renamed = tmp.renameTo(active)
            if (!renamed) {
                // На некоторых ФС renameTo поверх существующего не срабатывает:
                // пишем напрямую и убираем временный файл.
                active.writeText(lower.joinToString("\n", postfix = "\n"))
                tmp.delete()
            }
        }
    }
}

package mihon.data.ocr

import android.content.Context
import java.io.File
import java.io.InputStream
import logcat.LogPriority
import tachiyomi.core.common.util.system.logcat

/**
 * Частотный словарь русских словоформ для разбиения слипшегося OCR-текста
 * на слова (только вставка пробелов, без замены символов — словарная
 * «коррекция» запрещена правилами проекта).
 *
 * Источники (пересборка — `scripts/gen_ruwordlist.py`):
 *  * морфологический лексикон OpenCorpora;
 *  * ё/е-варианты каждой формы: OCR читает ё непоследовательно, и «НАМЁКА»
 *    обязано находиться так же, как «НАМЕКА»;
 *  * литературная лексика из прежней версии словаря (её в субтитрах нет);
 *  * сиды device-регрессий и однобуквенные служебные слова.
 *
 * Формы лежат в ассете `assets/ocr/ru_wordlist.txt` — по одной прописной
 * словоформе на строку. Раньше они были зашиты строковыми литералами в
 * RuWordListPartNNN.kt: 3 млн форм раздували APK на ~65 МБ (DEX), и установка
 * падала с `Failed to allocate … because only … allocatable` (ENOSPC) на
 * телефонах с малым запасом свободного места. Ассет сжимается штатно внутри
 * APK и в DEX не попадает.
 *
 * Размер словаря — это ровно то, от чего зависит «недоскан»: DP-разбиение
 * слипшегося прогона требует, чтобы КАЖДЫЙ сегмент был известным словом.
 * На 7008 формах полноценно делились редкие строки («ЗАЭТИГОДЫЯ…»), на
 * 61 028 — подавляющее большинство словоупотреблений корпуса, а на 294 662
 * (59 частей) добавляется книжная и разговорная лексика, которой в субтитрах
 * почти нет. Словарь только разрешает вставить границу: неизвестное остаётся
 * как есть.
 */
object RuWordList {

    private const val ASSET_PATH = "ocr/ru_wordlist.txt"

    /**
     * Ожидаемое число словоформ. Используется только как подсказка для
     * начальной ёмкости [upper]: точное значение не критично, лишние или
     * недостающие формы просто попадут/не попадут в набор.
     */
    private const val EXPECTED_FORMS = 3_014_492

    /**
     * Куда смотреть в JVM-юнит-тестах, где нет AssetManager. Gradle запускает
     * тесты с рабочим каталогом = каталог модуля `data`, поэтому первый путь
     * ведёт к тому же файлу, что упакован в APK.
     */
    private val TEST_SOURCE_CANDIDATES = listOf(
        "src/main/assets/$ASSET_PATH",
        "data/src/main/assets/$ASSET_PATH",
    )

    @Volatile
    private var opener: (() -> InputStream)? = null

    /**
     * Привязывает словарь к ассету приложения и вызывается на старте (`App`)
     * до первого обращения к [upper]. Без вызова доступен только тестовый
     * источник из исходников модуля.
     */
    fun configure(context: Context) {
        opener = { context.assets.open(ASSET_PATH) }
    }

    private fun openSource(): InputStream? {
        opener?.let { return it() }
        for (path in TEST_SOURCE_CANDIDATES) {
            val file = File(path)
            if (file.isFile) return file.inputStream()
        }
        return null
    }

    /** Словоформы ВЕРХНИМ регистром: прогоны OCR приходят капсом. */
    val upper: Set<String> by lazy(LazyThreadSafetyMode.SYNCHRONIZED) {
        val stream = openSource()
        if (stream == null) {
            logcat(LogPriority.WARN) {
                "RuWordList: ассет $ASSET_PATH не найден — разбиение капса деградирует"
            }
            return@lazy emptySet<String>()
        }
        // Формы в файле уже прописные: вставляем как есть, без 3 млн uppercase().
        // Ёмкость под точное число элементов — рехэширования нет.
        val set = HashSet<String>((EXPECTED_FORMS / 0.75f).toInt() + 1)
        stream.bufferedReader(Charsets.UTF_8).use { reader ->
            while (true) {
                val line = reader.readLine() ?: break
                if (line.isNotEmpty()) set.add(line)
            }
        }
        set
    }
}

