package mihon.domain.ocr.service

import mihon.domain.ocr.model.OcrModel
import tachiyomi.core.common.preference.PreferenceStore
import tachiyomi.core.common.preference.getEnum

enum class ScanRegion {
    FULL_PAGE,   // Сканировать всю страницу (100%)
    TOP_HALF,    // Сканировать верхнюю часть (Top 50%)
    BOTTOM_HALF, // Сканировать нижнюю часть (Bottom 50%)
}

class OcrPreferences(
    private val preferenceStore: PreferenceStore,
) {

    fun ocrModel() = preferenceStore.getEnum("pref_ocr_model", OcrModel.CYRILLIC)

    /** Домен: для чего выбирается технология (игры / книги / приложения). */
    enum class OcrDomain { GAME, BOOK, APP }

    /**
     * Своя технология распознавания на домен: игры (скорость важнее),
     * книги, приложения-оверлей. Манга-конвейер читалки продолжает
     * использовать общий [ocrModel] — доменные движки подхватывают новые
     * пути захвата (игры/оверлей) через [engineForDomain].
     */
    fun gameOcrEngine() = preferenceStore.getEnum("pref_ocr_engine_game", OcrModel.FAST)
    fun bookOcrEngine() = preferenceStore.getEnum("pref_ocr_engine_book", OcrModel.CYRILLIC)
    fun appOcrEngine() = preferenceStore.getEnum("pref_ocr_engine_app", OcrModel.CYRILLIC)

    fun engineForDomain(domain: OcrDomain): OcrModel = when (domain) {
        OcrDomain.GAME -> gameOcrEngine().get()
        OcrDomain.BOOK -> bookOcrEngine().get()
        OcrDomain.APP -> appOcrEngine().get()
    }

    fun scanRegion() = preferenceStore.getEnum("pref_scan_region", ScanRegion.FULL_PAGE)

    // ---- Пресеты областей и типа контента ----
    // Тип контента (манга / манхва / комикс / сбалансированный) задаёт пресет
    // параметров детектора и порядок чтения. См. mihon.data.ocr.OcrTuning.
    fun contentType() = preferenceStore.getString("pref_ocr_content_type", "balanced")

    /** Авто-пресет типа контента по геометрии страницы: on/off. */
    fun autoPreset() = preferenceStore.getString("pref_ocr_auto_preset", "on")

    /**
     * Насколько дорого распознавать локально: accurate (вторая модель и
     * повтор с контрастом) или fast (один проход на реплику).
     * См. mihon.data.ocr.OcrLocalMode.
     */
    fun localMode() = preferenceStore.getString("pref_ocr_local_mode", "accurate")

    /** Разметка ударений («+» после ударного гласного) для RHVoice. */
    fun ruStress() = preferenceStore.getString("pref_ru_stress", "on")

    /** Память авто-пресета: «mangaId:presetId,…» (последние 60). */
    fun mangaPresetMap() = preferenceStore.getString("pref_manga_preset_map", "")

    /** Пресет голоса: пол (auto/male/female/neutral). */
    fun voicePresetGender() = preferenceStore.getString("pref_voice_preset_gender", "auto")

    /** Пресет голоса: возраст (infant/child/teen/adult/elderly). */
    fun voicePresetAge() = preferenceStore.getString("pref_voice_preset_age", "adult")

    // Область, которую пресет применяет по умолчанию. Хранится отдельно от
    // scanRegion(): пользователь может переопределить область, не теряя пресет.
    fun presetScanRegion() = preferenceStore.getString("pref_ocr_preset_region", "full")

    // Точные переопределения пресета. Пустая строка = «как в пресете».
    fun detectorThresholdOverride() = preferenceStore.getString("pref_ocr_detector_threshold", "")
    fun minComponentAreaOverride() = preferenceStore.getString("pref_ocr_min_area", "")
    fun maxTextBoxesOverride() = preferenceStore.getString("pref_ocr_max_boxes", "")
    fun wordGapFactorOverride() = preferenceStore.getString("pref_ocr_word_gap", "")
    fun minAcceptConfidenceOverride() = preferenceStore.getString("pref_ocr_min_confidence", "")
    fun shortTextConfidenceOverride() = preferenceStore.getString("pref_ocr_short_confidence", "")
    fun minCoverageOverride() = preferenceStore.getString("pref_ocr_min_coverage", "")
    fun rescueMaxLinesOverride() = preferenceStore.getString("pref_ocr_rescue_lines", "")

    fun autoOcrOnDownload() = preferenceStore.getBoolean("auto_ocr_on_download", false)

    fun owocrAddress() = preferenceStore.getString("pref_owocr_address", "ws://10.0.2.2:7331")

    fun useFallbackModels() = preferenceStore.getBoolean("pref_use_fallback_models", true)

    /**
     * Считать ли страницу без текста картинкой и не гонять резервную цепочку.
     *
     * Включено по умолчанию. Иначе каждая иллюстрация прогонялась ещё и
     * онлайн-движками с загрузкой картинки — авточтение на ней подвисало.
     */
    fun skipUntitledPages() = preferenceStore.getBoolean("pref_skip_untitled_pages", true)


    // Пресет цепочки фолбэков:
    //  auto      — умный порядок: онлайн при сети, локальные без сети
    //  online    — только онлайн-движки (GLENS -> ZEN_FREE -> GOOGLE)
    //  offline   — только локальные (TESSERACT -> FAST -> LEGACY)
    //  single    — без фолбэков, только выбранный движок
    fun fallbackPreset() = preferenceStore.getString("pref_fallback_preset", "auto")

    // Язык/регион распознавания для онлайнового GLENS-движка. Раньше были
    // жёстко зашиты ("ja"/"Asia/Tokyo"), из-за чего пользователь не мог читать
    // английские, русские и другие источники. Язык — BCP-47 (en, ru, ja,
    // ko, zh…), регион — IANA tz (необязателен).
    fun glensLanguage() = preferenceStore.getString("pref_glens_language", "ja")
    fun glensRegion() = preferenceStore.getString("pref_glens_region", "Asia/Tokyo")

    // OpenRouter Settings
    fun openrouterApiKey() = preferenceStore.getString("pref_openrouter_api_key", "")
    fun openrouterModel() = preferenceStore.getString("pref_openrouter_model", "google/gemini-2.5-flash")

    // Google AI / Gemini Settings
    fun googleApiKey() = preferenceStore.getString("pref_google_api_key", "")
    fun googleModel() = preferenceStore.getString("pref_google_model", "gemini-2.5-flash")

    fun zenFreeEnabled() = preferenceStore.getBoolean("pref_zen_free_enabled", true)

    // Token Tracker & Usage Counter
    fun tokenUsageCount() = preferenceStore.getLong("pref_token_usage_count", 0L)
    fun incrementTokens(tokens: Long) {
        val current = tokenUsageCount().get()
        tokenUsageCount().set(current + tokens)
    }

    // Voice & Text-to-Speech Settings
    // Движки: system_tts (системные/локальные голоса), google_web (веб без
    // API-ключа, с сайта Google Translate), eleven_api (ElevenLabs по ключу)
    fun voiceEngine() = preferenceStore.getString("pref_voice_engine", "system_tts")

    /**
     * Основной голос. По умолчанию ПУСТО — голос выбирается автоматически.
     *
     * Раньше здесь стоял сетевой голос Google `ru-ru-x-dfa-network`: у новой
     * установки озвучка уходила в интернет без разрешения и без внятного
     * запроса. Пустое значение отдаёт выбор VoiceHelper.pickFor, который
     * ранжирует голоса «локальные → сетевые», поэтому по умолчанию читает
     * установленный локальный движок, а сетевой включается только если его
     * выбрали руками.
     */
    fun voiceName() = preferenceStore.getString("pref_voice_name", "")
    fun voiceSlots() = preferenceStore.getString("voice_slots", "[]")

    /**
     * Закреплённые голоса персонажей по книгам.
     *
     * Формат: {"<chapterId>": {"<ключ персонажа>": <слот>}, …}. Слот — это
     * номер, по которому голос выбирается автоматически (см.
     * TtsSpeaker.pickSlotVoice). Без этой карты голос персонажа держался
     * только в памяти сеанса: закрыл книгу — вернулся, и тот же герой мог
     * заговорить другим голосом.
     */
    fun bookVoiceSlots() = preferenceStore.getString("pref_book_voice_slots", "{}")

    /**

     * Читать только голосом телефона.
     *
     * Включено по требованию читателя: и авточтение, и одиночная реплика
     * произносятся системным движком, иначе — веб-голосом сети. Сетевой голос
     * не связан с голосами устройства: список голосов, который показывает
     * читалка, к нему отношения не имеет, и на выбранных страницах он молчит
     * или читает латиницей. С системным голосом список и озвучка согласованы.
     */
    fun voicePhoneOnly() = preferenceStore.getBoolean("pref_voice_phone_only", true)

    // Словари голосовых ролей и интонаций: персонаж → голос/питч/темп и
    // узор текста → пауза/питч/темп. Хранятся JSON-массивами, читаются в
    // [eu.kanade.tachiyomi.data.tts.VoiceRoleDictionary]
    // и [eu.kanade.tachiyomi.data.tts.VoiceIntonationDictionary].
    fun voiceRoles() = preferenceStore.getString("voice_role_dict", "[]")
    fun voiceIntonations() = preferenceStore.getString("voice_intonation_dict", "[]")

    /**
     * Роли голосов, привязанные к конкретной книге: JSON-объект
     * `{ "<mangaId>": [ роли ], … }`.
     *
     * Глобальный [voiceRoles] один на всё приложение, и это было проблемой:
     * голос, назначенный Аки в «Миэруко-тян», тут же перехватывал такую же
     * подпись в любой другой книге. Книжный словарь лежит поверх и имеет
     * приоритет, поэтому озвучка персонажа работает только там, где её
     * назначили, а общие правила продолжают применяться везде.
     */
    fun voiceRolesByBook() = preferenceStore.getString("voice_role_dict_by_book", "{}")


    fun speechRate() = preferenceStore.getFloat("pref_speech_rate", 1.0f)
    fun speechPitch() = preferenceStore.getFloat("pref_speech_pitch", 1.0f)
    fun ttsWebLanguage() = preferenceStore.getString("pref_tts_web_lang", "ru")
    fun elevenApiKey() = preferenceStore.getString("pref_eleven_api_key", "")
    fun elevenVoiceId() = preferenceStore.getString("pref_eleven_voice_id", "")

    // Edge TTS (Microsoft): онлайн-голоса без API-ключа. Голос — ShortName из
    // публичного списка edge-tts (напр. ru-RU-SvetlanaNeural, en-US-EmmaMultilingualNeural).
    fun edgeVoice() = preferenceStore.getString("pref_edge_voice", "ru-RU-SvetlanaNeural")

    // Фильтр языка в списке голосов Edge TTS:
    // "auto" = язык выбранного голоса, "" = все языки, "🌐" = мультиязычные,
    // иначе двухбуквенный код языка.
    fun edgeLanguage() = preferenceStore.getString("pref_edge_language", "auto")

    // Пресеты голосов: отдельно женский и мужской системные голоса.
    // При автоозвучке реплики могут чередоваться по полу говорящего.
    fun voiceFemale() = preferenceStore.getString("pref_voice_female", "")
    fun voiceMale() = preferenceStore.getString("pref_voice_male", "")

    // Авто-OCR видимой страницы + мгновенная озвучка результата
    fun autoScanAndSpeak() = preferenceStore.getBoolean("pref_auto_scan_speak", false)

    /**
     * Режим авточтения ПОД КОНКРЕТНУЮ модель (ранее — один общий конвейер
     * для всех движков; GLens повторял целые реплики, Space Bunny медлил
     * на переводе — теперь поведение подстраивается под природу движка):
     *  - "stream" — «Строки сразу»: перевод страницы идёт в фоне, озвучка
     *    стартует немедленно с оригинала и подхватывает перевод по мере
     *    готовности. Для быстрых OCR / чтения исходного языка.
     *  - "bubble" — «Баблоны с буфером слов» (дефолт): стабильный
     *    по-баллонный путь с отсечением уже прочитанных слов.
     *  - "page"   — «Вся страница одной озвучкой»: кадр склеивается в
     *    одну реплику (дубль-приставка у старых слов всё равно срезается).
     */
    fun autoReadModeFor(model: OcrModel) = preferenceStore.getString(
        "pref_autoread_mode_" + model.name.lowercase(),
        "bubble",
    )

    /** Последний замер скорости кадра авточтения (мс) для движка [model]. */
    fun autoReadLastMs(model: OcrModel) = preferenceStore.getString(
        "pref_autoread_last_ms_" + model.name.lowercase(),
        "",
    )


    // Пресет направления сканирования/чтения страницы:
    // rtl (манга), ltr (комиксы), vertical (вебтуны)
    fun scanReadingOrder() = preferenceStore.getString("pref_scan_reading_order", "rtl")

    // ---- Авточтение (браузер и читалка) ----
    // Язык, который читаем; всё остальное на кадре игнорируется:
    // ru / en / ja / ko / zh / any
    fun autoReadLanguage() = preferenceStore.getString("pref_autoread_language", "ru")

    // Переводить ли реплики на русский перед озвучкой (для en/ja/…)
    fun autoReadTranslate() = preferenceStore.getBoolean("pref_autoread_translate", true)

